import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and empty policy ---
  it.todo("quotes an empty item list as premium 5 G (processing fee only)");

  // --- Quote: base premiums per main item type (price list catalogue) ---
  it.todo("quotes a sword for a 2-year customer's... base premium 100 G -- see dedicated base-premium tests below");
  it.todo("quotes a single sword with no modifiers -- base 100 G + 10 G first insurance + 5 G fee = 115 G");
  it.todo("quotes a single amulet with no modifiers -- base 60 G + 6 G first insurance + 5 G fee = 71 G");
  it.todo("quotes a single staff with no modifiers -- base 80 G + 8 G first insurance + 5 G fee = 93 G");
  it.todo("quotes a single potion with no modifiers -- base 40 G + 4 G first insurance + 5 G fee = 49 G");

  // --- Quote: component base premiums and building blocks ---
  it.todo("quotes a single rune -- component base premium 25 G");
  it.todo("quotes a single moonstone -- component base premium 25 G");
  it.todo("quotes 2 runes -- base premium 50 G (no block)");
  it.todo("quotes 3 runes -- base premium 60 G (block applies)");
  it.todo("quotes 4 runes -- base premium 100 G (no block; block requires exactly 3)");
  it.todo("quotes 7 runes -- base premium 175 G (no block; 7 is not exactly 3)");
  it.todo("quotes 2 runes + 1 moonstone -- base premium 75 G (no block: alike means same type)");
  it.todo("quotes 3 runes + 3 moonstones -- base premium 120 G (two separate blocks of alike components)");

  // --- Quote: item-specific modifiers ---
  it.todo("adds a 50% curse surcharge to the cursed item's base premium");
  it.todo("adds a 30% high-enchantment surcharge at enchantment exactly 5");
  it.todo("adds no high-enchantment surcharge at enchantment 4");
  it.todo("applies both curse and high-enchantment surcharges to a cursed sword with enchantment 5");
  it.todo("applies the curse surcharge only to the cursed item, not the policy total -- cursed sword + plain amulet -> 210 G before policy modifiers and fee");

  // --- Quote: policy-wide modifiers ---
  it.todo("applies the 20% loyalty discount at exactly 2 years with MHPCO");
  it.todo("applies no loyalty discount at 1 year with MHPCO");
  it.todo("applies the 10% first-insurance surcharge to every item in every quote, regardless of customer history");
  it.todo("applies a 15% follow-up discount on the customer's second quote");
  it.todo("applies no follow-up discount on the customer's first quote");
  it.todo("adds the 5 G processing fee at the very end, after all other modifiers");

  // --- Quote: rounding in MHPCO's favor ---
  it.todo("rounds a premium of 197.5 G up to 198 G (MHPCO's favor)");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");

  // --- Quote: integration examples ---
  it.todo("integration: newcomer (0 years, first contract) with a cursed steel sword enchantment 3 -- premium 165 G");
  it.todo("integration: 3-year customer's second quote, cursed steel sword enchantment 7 -- premium 160 G");

  // --- Quote: rejection ---
  it.todo("rejects a quote containing an unknown item type -- CLI exits non-zero, error on stderr, no results on stdout");

  // --- Claim: standard reimbursement and deductible ---
  it.todo("pays out full damage minus the 100 G deductible for a steel sword enchantment 3, damage 500 G -- payout 400 G");
  it.todo("pays out full damage minus the 100 G deductible for a rune (no enchantment, no material), damage 200 G -- payout 100 G");
  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G -> payout 600 G");

  // --- Claim: special clauses ---
  it.todo("reimburses 50% of damage for enchantment exactly 8 -- dragon sword enchantment 8, damage 1000 G -> payout 400 G");
  it.todo("reimburses dragon material fully -- dragon sword enchantment 5, damage 800 G -> payout 700 G");
  it.todo("prefers the 50% rule when both clauses apply -- dragon sword enchantment 9, damage 1000 G -> payout 400 G");
  it.todo("applies only the high-enchantment clause for a steel sword enchantment 9, damage 1000 G -> payout 400 G");

  // --- Claim: insurance sum and cap ---
  it.todo("caps payout at twice the insurance sum -- single sword policy: insurance sum 1000 G, cap 2000 G");
  it.todo("sums insurance values across items -- sword + amulet: insurance sum 1600 G, cap 3200 G");
  it.todo("computes insurance sum 2000 G and cap 4000 G for a policy covering two swords");
  it.todo("computes insurance sum 1750 G and cap 3500 G for a sword + 3 runes (block affects premium only)");
  it.todo("bases the cap on unmodified insurance value -- cursed sword (premium 165 G) still has cap 2000 G");
  it.todo("reports remainingCap after a claim -- sword policy, claim 1500 G -> payout 1400 G, remainingCap 600 G");
  it.todo("reduces a later payout to the remaining cap -- second claim of 1500 G -> payout 600 G, remainingCap 0 G");

  // --- Claim: multiple items of the same type ---
  it.todo("treats each damage entry of the same itemType as a separate damage with its own deductible -- two swords damaged");
  it.todo("rejects a claim with more damage entries of a type than the policy covers -- CLI exits non-zero, error on stderr");

  // --- Claim: rounding in MHPCO's favor ---
  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favor)");

  // --- Claim: rejection ---
  it.todo("rejects a claim whose damaged item is not part of the policy (amulet damaged, only a sword insured) -- CLI exits non-zero, error on stderr");
  it.todo("rejects a claim referencing an unknown item type -- CLI exits non-zero, error on stderr");
  it.todo("rejects a claim with a negative damage amount (-200) -- CLI exits non-zero, error on stderr");

  // --- CLI: scenario protocol ---
  it.todo("CLI reads a JSON scenario from stdin and writes {results: [...]} to stdout in step order");
  it.todo("CLI resolves a claim step's policy field to the zero-based index of the earlier quote step");
  it.todo("CLI processes the schema example -- amulet quote then 200 G amulet claim -- producing a premium and a payout/remainingCap result");
});
EOF
