export interface Customer {
  readonly yearsWithMHPCO: number;
  readonly previousContracts: number;
}

export interface Item {
  readonly type: string;
}

/** MHPCO adds a flat processing fee to every premium, at the very end. */
const PROCESSING_FEE_G = 5;

/** Every item in a quote is treated as a first insurance. */
const FIRST_INSURANCE_SURCHARGE = 0.1;

const SWORD_BASE_PREMIUM_G = 100;

function itemBasePremium(_item: Item): number {
  return SWORD_BASE_PREMIUM_G;
}

