 * MHPCO offers a building block of exactly 3 alike components — components of
 * the same type — at a special base premium instead of the per-component rate.
 */
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM_G = 60;

/** The base premium of a single main item according to the MHPCO price list. */
function mainItemBasePremium(item: Item): number {
  return MAIN_ITEM_BASE_PREMIUM_G[item.type];
}

/** The base premium MHPCO charges for a number of alike components. */
function alikeComponentsBasePremium(count: number): number {
  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM_G : count * COMPONENT_BASE_PREMIUM_G;
}

function countByType(items: readonly Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

/** The sum of the base premiums of all insured items, before any modifier. */
export function policyBasePremium(items: readonly Item[]): number {
  const components = items.filter(isComponent);
  const mainItems = items.filter((item) => !isComponent(item));
  const mainItemsTotal = mainItems.reduce((sum, item) => sum + mainItemBasePremium(item), 0);
  let componentsTotal = 0;
  for (const count of countByType(components).values()) {
    componentsTotal += alikeComponentsBasePremium(count);
  }
  return mainItemsTotal + componentsTotal;
}''')
