import { policyBasePremium, type Item } from "./price-list.js";

export type { Item };

export interface Customer {
  readonly yearsWithMHPCO: number;
  readonly previousContracts: number;
}

/** MHPCO adds a flat processing fee to every premium, at the very end. */
const PROCESSING_FEE_G = 5;

/** Every item in a quote is treated as a first insurance: 10 % surcharge. */
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const PERCENT = 100;

/**
 * A policy-wide modifier: it is charged on the policy base premium rather than
 * on a single item's base premium. Every item in a quote counts as a first
 * insurance regardless of customer history, so the initial assessment
 * surcharge is charged on the whole policy base premium.
 */
function initialAssessmentSurcharge(policyBase: number): number {
  return (policyBase * FIRST_INSURANCE_SURCHARGE_PERCENT) / PERCENT;
}

/**
 * MHPCO rounds every final amount in its own favour: a premium the customer
 * owes is rounded up. Only the final amount is rounded; intermediate amounts
 * are kept as fractions.
 */
function roundPremiumInMHPCOFavour(premium: number): number {
  return Math.ceil(premium);
}

export function quote(_customer: Customer, items: readonly Item[]): number {
  const policyBase = policyBasePremium(items);
  const premium = policyBase + initialAssessmentSurcharge(policyBase) + PROCESSING_FEE_G;
  return roundPremiumInMHPCOFavour(premium);
}
