/**
 * The MHPCO price list: what each insured thing costs before any modifier.
 *
 * This module owns catalogue knowledge only — which item types the office
 * recognises and the base premium it charges for them. It deliberately knows
 * nothing about surcharges, discounts, the processing fee or rounding: those
 * are underwriting policy and change for entirely different reasons.
 */

export interface Item {
  readonly type: string;
}

/** The MHPCO price list for main items: base premium in G per item type. */
const MAIN_ITEM_BASE_PREMIUM_G: Readonly<Record<string, number>> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

/**
 * Components — runes, moonstones and their kin — are not listed individually on
 * the main price list. MHPCO charges one uniform rate per component.
 */
const COMPONENT_BASE_PREMIUM_G = 25;

const COMPONENT_TYPES: readonly string[] = ["rune", "moonstone"];

function isComponent(item: Item): boolean {
  return COMPONENT_TYPES.includes(item.type);
}

/**
 * MHPCO offers a building block of exactly 3 alike components — components of
 * the same type — at a special base premium instead of the per-component rate.
 */
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM_G = 60;

/** The base premium of a single main item according to the MHPCO price list. */
function mainItemBasePremium(item: Item): number {
  return MAIN_ITEM_BASE_PREMIUM_G[item.type];
}

/** The base premium MHPCO charges for a number of alike components. */
function alikeComponentsBasePremium(count: number): number {
  return count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM_G : count * COMPONENT_BASE_PREMIUM_G;
}

/**
 * MHPCO reads "alike" as "of the same type": two runes and a moonstone are not
 * three alike components, and a policy covering 3 runes and 3 moonstones earns
 * two separate building blocks. Grouping components by type is therefore the
 * office's ruling on what counts as alike, and the sizes of these groups are
 * what the block rule is applied to.
 */
function alikeComponentGroupSizes(components: readonly Item[]): number[] {
  const sizeByType = new Map<string, number>();
  for (const component of components) {
    sizeByType.set(component.type, (sizeByType.get(component.type) ?? 0) + 1);
  }
  return [...sizeByType.values()];
}

/**
 * Components are priced per group of alike components, not per item: MHPCO
 * gathers the alike ones together first so that a building block can be
 * recognised, then prices each group on its own.
 */
function componentsBasePremium(components: readonly Item[]): number {
  return alikeComponentGroupSizes(components).reduce(
    (total, groupSize) => total + alikeComponentsBasePremium(groupSize),
    0,
  );
}

