python3 - <<'PY'
p='src/claim-office.ts'
s=open(p).read()
s=s.replace('''/** The insured item a damage report entry refers to. */
function damagedItem(policy: Policy, damage: Damage): Item {
  const item = policy.items.find((insured) => insured.type === damage.itemType);
  if (item === undefined) {
    throw new Error(`the policy does not cover an item of type "${damage.itemType}"`);
  }
  return item;
}''','''/**
 * Matches the damage entries of one report to the items a policy covers.
 *
 * A damaged item is claimed for once: two entries of the same type need two
 * insured items of that type. A report naming more of a type than the policy
 * covers — or a type it does not cover at all — is one the office refuses.
 */
function coverageOf(policy: Policy): (damage: Damage) => Item {
  const unclaimed = [...policy.items];
  return (damage) => {
    const index = unclaimed.findIndex((insured) => insured.type === damage.itemType);
    if (index === -1) {
      throw new Error(`the policy does not cover a further item of type "${damage.itemType}"`);
    }
    return unclaimed.splice(index, 1)[0]!;
  };
}''')
s=s.replace('  const owed = incidentReimbursement(incident, (damage) => damagedItem(policy, damage));',
            '  const owed = incidentReimbursement(incident, coverageOf(policy));')
open(p,'w').write(s)
