cat > src/cli.ts <<'EOF'
/**
 * The `claim-office` command: MHPCO's counter clerk.
 *
 * This module is an adapter and owns no underwriting rule. It reads a scenario
 * from stdin, puts each step to the office in turn, and writes the office's
 * answers to stdout. A step the office refuses ends the whole scenario: the
 * clerk writes the reason to stderr and reports failure, leaving stdout empty.
 */

import { readFileSync } from "node:fs";
import {
  claim,
  createPolicy,
  type Customer,
  type Incident,
  type Item,
  type Policy,
} from "./claim-office.js";
import { afterWritingAContract } from "./customer-standing.js";

interface QuoteStep {
  readonly op: "quote";
  readonly items: readonly Item[];
}

interface ClaimStep {
  readonly op: "claim";
  readonly policy: number;
  readonly incident: Incident;
}

type Step = QuoteStep | ClaimStep;

interface Scenario {
  readonly customer: { readonly yearsWithMHPCO: number };
  readonly steps: readonly Step[];
}

type StepResult = { readonly premium: number } | { readonly payout: number; readonly remainingCap: number };

/** The scenario as the office sees it: the customer, and the policies written so far. */
interface Counter {
  customer: Customer;
  readonly policies: Map<number, Policy>;
}

function handleQuote(counter: Counter, step: QuoteStep, stepIndex: number): StepResult {
  const policy = createPolicy(counter.customer, step.items);
  counter.policies.set(stepIndex, policy);
  counter.customer = afterWritingAContract(counter.customer);
  return { premium: policy.premium };
}

function handleClaim(counter: Counter, step: ClaimStep): StepResult {
  const policy = counter.policies.get(step.policy);
  if (policy === undefined) {
    throw new Error(`step ${step.policy} did not create a policy`);
  }
  const settlement = claim(policy, step.incident);
  counter.policies.set(step.policy, settlement.policy);
  return { payout: settlement.payout, remainingCap: settlement.policy.remainingCap };
}

function runScenario(scenario: Scenario): readonly StepResult[] {
  const counter: Counter = {
    customer: { yearsWithMHPCO: scenario.customer.yearsWithMHPCO, previousContracts: 0 },
    policies: new Map<number, Policy>(),
  };
  return scenario.steps.map((step, stepIndex) =>
    step.op === "quote" ? handleQuote(counter, step, stepIndex) : handleClaim(counter, step),
  );
}

function main(): void {
  const scenario = JSON.parse(readFileSync(0, "utf8")) as Scenario;
  process.stdout.write(JSON.stringify({ results: runScenario(scenario) }));
}

try {
  main();
} catch (error) {
  process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
  process.exit(1);
}
EOF
